import { format } from 'prettier';
import { describe, expect, it } from 'vitest';
import { singleLineDeclarations } from '../src/contract-snapshot-store';

const GENERATED_HEADER = [
  '// ⚠️  GENERATED FILE - DO NOT EDIT',
  "// This file is automatically generated by 'prisma contract emit'.",
  '// To regenerate, run: prisma contract emit',
].join('\n');

const FORMATTED_DECLARATIONS = `import type { QueryOperationTypes as PgAdapterQueryOps } from '@prisma/orm-postgres/adapter/operation-types';
import type { CodecTypes as PgTypes } from '@prisma/orm-postgres/target/codec-types';

import type {
  ContractWithTypeMaps,
  TypeMaps as TypeMapsType,
} from '@prisma/orm-postgres/family-contract/types';
import type {
  Contract as ContractType,
  ExecutionHashBase,
  ProfileHashBase,
  StorageHashBase,
} from '@prisma/orm-postgres/contract/types';

export type StorageHash =
  StorageHashBase<'4a96b488a4ce92b434e5f7d6607b6435c0955f0d36b0018077045787764240e6'>;
export type ExecutionHash = ExecutionHashBase<string>;
export type ProfileHash =
  ProfileHashBase<'3916f444a8a17ad749191acf9e08dad97d1a327b88c2f1d45d12f240296aa8b2'>;

export type CodecTypes = PgTypes;
export type QueryOperationTypes = PgAdapterQueryOps<CodecTypes>;
type DefaultLiteralValue<CodecId extends string, _Encoded> = CodecId extends keyof CodecTypes
  ? CodecTypes[CodecId]['output']
  : _Encoded;

export type FieldOutputTypes = { readonly public: Record<string, never> };
export type TypeMaps = TypeMapsType<CodecTypes, QueryOperationTypes, FieldOutputTypes>;

type ContractBase = Omit<
  ContractType<{
    readonly namespaces: {
      readonly public: {
        readonly id: 'public';
        readonly kind: 'postgres-schema';
        readonly entries: { readonly table: {} };
      };
    };
    readonly storageHash: StorageHash;
  }>,
  'roots' | 'domain'
> & {
  readonly target: 'postgres';
  readonly default: DefaultLiteralValue<'sqlite/json@1', '"it\\'s" // not a comment'>;
  readonly capabilities: {
    readonly postgres: {
      readonly lateral: true;
      readonly returning: true;
    };
  };
  readonly meta: {};

  readonly profileHash: ProfileHash;
};

export type Contract = ContractWithTypeMaps<ContractBase, TypeMaps>;
`;

async function formatDeclarations(text: string): Promise<string> {
  const formatted = await format(text, {
    parser: 'typescript',
    singleQuote: true,
    semi: true,
    printWidth: 100,
    objectWrap: 'collapse',
  });
  return formatted
    .split('\n')
    .filter((line) => line.trim() !== '')
    .join('\n');
}

describe('singleLineDeclarations', () => {
  it('formats back to the same declarations', async () => {
    const singleLine = singleLineDeclarations(`${GENERATED_HEADER}\n${FORMATTED_DECLARATIONS}`);

    const headerEnd = singleLine.indexOf('*/ ') + '*/ '.length;
    expect({
      header: singleLine.slice(0, headerEnd),
      body: await formatDeclarations(singleLine.slice(headerEnd)),
    }).toEqual({
      header:
        "/* ⚠️  GENERATED FILE - DO NOT EDIT This file is automatically generated by 'prisma contract emit'. To regenerate, run: prisma contract emit */ ",
      body: await formatDeclarations(FORMATTED_DECLARATIONS),
    });
  });

  it('writes one line ending in a newline', () => {
    const singleLine = singleLineDeclarations(`${GENERATED_HEADER}\n${FORMATTED_DECLARATIONS}`);

    expect(singleLine.indexOf('\n')).toBe(singleLine.length - 1);
  });

  it('joins an existing block comment', () => {
    expect(singleLineDeclarations('/**\n * Placeholder.\n */\nexport {};\n')).toBe(
      '/** * Placeholder. */ export {};\n',
    );
  });
});
